def maxDepth(arr):
    if not arr or arr[0] is None: return 0
    # height via level count for complete simulation: depth = ceil(log2(n+1)) for perfect, else BFS sim
    # simplified: count levels by simulating BFS on array representation
    from collections import deque
    q=deque([0]); depth=0
    while q:
        depth+=1
        nxt=[]
        for i in q:
            l=2*i+1; r=2*i+2
            if l < len(arr) and arr[l] is not None: nxt.append(l)
            if r < len(arr) and arr[r] is not None: nxt.append(r)
        q=deque(nxt)
    return depth

def canFinish(numCourses, prerequisites):
    from collections import defaultdict, deque
    g=defaultdict(list); indeg=[0]*numCourses
    for a,b in prerequisites: g[b].append(a); indeg[a]+=1
    q=deque([i for i,d in enumerate(indeg) if d==0])
    seen=0
    while q:
        u=q.popleft(); seen+=1
        for v in g[u]:
            indeg[v]-=1
            if indeg[v]==0: q.append(v)
    return seen==numCourses

def invertTree(arr):
    if not arr or arr[0] is None: return arr
    n=len(arr)
    out=[None]*n; out[0]=arr[0]
    from collections import deque
    q=deque([0]); origin={0:0}; pos=1
    while q and pos<n:
        out_pos=q.popleft(); oi=origin[out_pos]
        l=2*oi+1; r=2*oi+2
        for c in (r,l):
            if c<n and pos<n:
                out[pos]=arr[c]; origin[pos]=c
                if arr[c] is not None: q.append(pos)
                pos+=1
    return out

