    out=[]; start=0; end=1; n=len(arr)
    while start<n:
        level=[]
        for i in range(start,min(end,n)):
            if arr[i] is not None: level.append(arr[i])
        if level: out.append(level)
        start=end; end=2*end+1
    return out

def isSymmetric(arr):
    if not arr or arr[0] is None: return True
    start=0; end=1; n=len(arr)
    while start<n:
        lo,hi=start,min(end,n)-1
        while lo<hi:
            if (arr[lo] is not None or arr[hi] is not None) and arr[lo]!=arr[hi]:
                return False
            lo+=1; hi-=1
        start=end; end=2*end+1
    return True

