def sortedArrayToBST(nums):
    def build(lo,hi):
        if lo>hi: return None
        m=(lo+hi)//2
        return (nums[m], build(lo,m-1), build(m+1,hi))
    t=build(0,len(nums)-1)
    out=[]; queue=[t]
    while queue and any(x is not None for x in queue):
        nxt=[]
        for node in queue:
            if node is None:
                out.append(None); continue
            out.append(node[0]); nxt.append(node[1]); nxt.append(node[2])
        queue=nxt
    return out

